begin;
create extension if not exists pgcrypto;
create table if not exists logistics_supply_plans(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,plan_no text not null,status text not null default 'draft' check(status in ('draft','approved','released','closed','cancelled')),planned_date date not null default current_date,notes text,created_by uuid,approved_by uuid,created_at timestamptz not null default now(),unique(tenant_id,plan_no));
create table if not exists logistics_vehicles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,plate_no text not null,title text not null,vehicle_type text,capacity numeric(20,3) default 0,status text not null default 'available' check(status in ('available','assigned','maintenance','inactive')),created_at timestamptz not null default now(),unique(tenant_id,plate_no));
create table if not exists logistics_drivers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,name text not null,mobile text,license_no text,license_expiry date,status text not null default 'active' check(status in ('active','inactive','suspended')),created_at timestamptz not null default now());
create table if not exists logistics_routes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,code text not null,name text not null,origin text,destination text,distance_km numeric(20,3) default 0,status text not null default 'active',created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists logistics_supply_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,order_no text not null,plan_id uuid references logistics_supply_plans(id),status text not null default 'draft' check(status in ('draft','submitted','approved','assigned','shipped','delivered','cancelled')),origin text not null,destination text not null,cargo_description text,quantity numeric(20,3) default 0,requested_date date,notes text,created_by uuid,approved_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,order_no));
create table if not exists logistics_shipments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,shipment_no text not null,status text not null default 'planned' check(status in ('planned','assigned','picked_up','in_transit','delivered','failed','cancelled')),supply_order_id uuid references logistics_supply_orders(id),route_id uuid references logistics_routes(id),vehicle_id uuid references logistics_vehicles(id),driver_id uuid references logistics_drivers(id),origin text not null,destination text not null,tracking_code text,dispatch_at timestamptz,delivered_at timestamptz,delivered_reason text,failed_reason text,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,shipment_no),unique(tenant_id,tracking_code));
create table if not exists logistics_delivery_events(id bigserial primary key,tenant_id uuid not null,shipment_id uuid not null references logistics_shipments(id) on delete cascade,status text not null,location text,description text,actor_user_id uuid,occurred_at timestamptz not null default now());
create table if not exists logistics_events(id bigserial primary key,tenant_id uuid not null,entity_type text not null,entity_id uuid not null,event_type text not null,from_status text,to_status text,actor_user_id uuid,reason text,created_at timestamptz not null default now());
insert into platform_modules(code,title,is_active) values('12-logistics-supply','زنجیره تأمین و لجستیک',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values('read','مشاهده لجستیک','modules:12-logistics-supply:read'),('write','ثبت لجستیک','modules:12-logistics-supply:write'),('dispatch','اعزام','modules:12-logistics-supply:dispatch'),('track','رهگیری','modules:12-logistics-supply:track'),('deliver','تحویل','modules:12-logistics-supply:deliver'))v(a,t,p) where m.code='12-logistics-supply' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;
commit;